pub fn prime_num(n: u64) -> bool {
    // By definition in the prompt, n is at least 2,
    // but we can still guard against smaller inputs.
    if n < 2 {
        return false;
    }

    // We only need to test divisors up to √n.
    // To avoid potential overflow in `i * i`, we use `i <= n / i`.
    let mut i = 2;
    while i <= n / i {
        if n % i == 0 {
            return false;
        }
        i += 1;
    }
    true
}

